import {
  Group,
  PlaneGeometry,
  MeshBasicNodeMaterial,
  EdgesGeometry,
  LineBasicMaterial,
  LineLoop,
} from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // Default dimensions matching the atlas source (512x320 → 1.6 aspect)
  const width = 1.6;
  const height = 1.0;
  const geometry = new PlaneGeometry(width, height);

  // Material – will be updated with loaded texture
  const material = new MeshBasicNodeMaterial({
    color: config.colors?.surface ?? '#0b0b10',
    transparent: true,
  });

  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Load texture
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.color.set('#ffffff');
      material.needsUpdate = true;
    });
  }

  // Accent edge on focus / hover
  const edges = new EdgesGeometry(geometry);
  const edgeMaterial = new LineBasicMaterial({
    color: config.colors?.accent ?? '#ff2a38',
    transparent: true,
    opacity: 0.9,
  });
  const edgeLine = new LineLoop(edges, edgeMaterial);
  edgeLine.visible = false; // hidden by default, shown on hover
  group.add(edgeLine);

  // Animation state
  const tlRiseIn = gsap.timeline({ paused: true });
  const tlPressDown = gsap.timeline({ paused: true });

  tlRiseIn.to(group.position, {
    y: group.position.y + 0.15,
    duration: 0.5,
    ease: 'power3.out',
  });

  tlPressDown.to(group.scale, {
    x: 0.97,
    y: 0.97,
    z: 0.97,
    duration: 0.12,
    ease: 'back.out(1.7)',
    yoyo: true,
    repeat: 1,
  });

  // Interaction handlers
  group.userData.handlers = {
    pointerover: () => {
      edgeLine.visible = true;
      tlRiseIn.play();
    },
    pointerout: () => {
      edgeLine.visible = false;
      tlRiseIn.reverse();
    },
    click: (event) => {
      tlPressDown.play();
      ctx.emit('hub-journal.select', { data: config.data ?? null });
    },
  };

  // Cleanup
  group.userData.cleanup = () => {
    tlRiseIn.kill();
    tlPressDown.kill();
    geometry.dispose();
    material.dispose();
    edgeMaterial.dispose();
    edges.dispose();
  };

  return group;
}
